spec.expr:
topk(5,
  sum by (host_name) (rate(storage_io_bytes_total{storage_type="storage_system"}[5m]))
)

sum by (vendor) (
  storage_usage_bytes{storage_type="storage_system", storage_provisioning_state="used"}
)

sum by (vendor) (
  storage_usage_bytes{storage_type="storage_system", storage_provisioning_state="used"}
)
/
sum by (vendor) (
  storage_usage_bytes{storage_type="storage_system", storage_provisioning_state=~"used|free"}
)

(
  count(ALERTS{alertstate="firing",severity="warning", alertname=~"MetricsHub-Storage-.*"})
  or vector(0)
)
+ on()
(
  sum(
    max by (host_name, hw_type, id) (
      hw_status{state=~"degraded|predicted_failure", host_name=~"$host_name"} == 1
    )
  )
  or vector(0)
)

label_join(
(
  storage_usage_bytes{host_name=~"$host_name", storage_type="pool", storage_provisioning_state="used"}
  / ignoring(storage_provisioning_state)
  storage_limit_bytes{host_name=~"$host_name", storage_type="pool"}
)
-
(
  storage_usage_bytes{host_name=~"$host_name", storage_type="pool", storage_provisioning_state="used"} offset $__range
  / ignoring(storage_provisioning_state)
  storage_limit_bytes{host_name=~"$host_name", storage_type="pool"} offset $__range
),
  "id", "/", "host_name", "id"
)

label_join(
storage_usage_bytes{host_name=~"$host_name", storage_type="pool", storage_provisioning_state="used"}
/ ignoring(storage_provisioning_state)
storage_limit_bytes{host_name=~"$host_name", storage_type="pool"},
  "id", "/", "host_name", "id"
)

label_join(
storage_provisioning_bytes{host_name=~"$host_name", storage_type="pool", storage_provisioning_state="subscribed"}
/ ignoring(storage_provisioning_state)
storage_limit_bytes{host_name=~"$host_name", storage_type="pool"},
  "id", "/", "host_name", "id"
)

label_join(
(
  (
    storage_limit_bytes{host_name=~"$host_name", storage_type="pool"}
    - ignoring(storage_provisioning_state)
    storage_usage_bytes{host_name=~"$host_name", storage_type="pool", storage_provisioning_state="used"}
  )
  / ignoring(storage_provisioning_state)
  deriv(
    storage_usage_bytes{host_name=~"$host_name", storage_type="pool", storage_provisioning_state="used"}[$__range]
  )
),
  "id", "/", "host_name", "id"
) > 0

(
  storage_usage_bytes{
    storage_type="storage_system",
    storage_provisioning_state="free"
  }
  / ignoring(storage_provisioning_state)
  deriv(
    storage_usage_bytes{
      storage_type="storage_system",
      storage_provisioning_state="used"
    }[$__range]
  )
) > 0

topk(5,
  sum by (storage_consumer_name) (
    rate(storage_io_bytes_total{storage_type="volume", storage_consumer_state="mapped", storage_consumer_name!="", storage_io_direction=~"read|write"}[$__range])
  )
)

count(
  count by (storage_consumer_name) (
    storage_limit_bytes{storage_type="volume",storage_consumer_name!="", storage_consumer_state="mapped"}
  )
)

label_replace(
  count(
    sum by (host_name, id) (
      storage_limit_bytes{storage_type="volume", netapp_storage_type!~"volume|lun"}
    )
    and on (host_name, id)
    storage_usage_bytes{storage_type="volume", netapp_storage_type!~"volume|lun", storage_consumer_state="mapped"}
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(storage_operations_total{storage_type="volume", netapp_storage_type!~"volume|lun", storage_io_direction=~"read|write"}[$__range])
      ) > 0.001
    )
  ),
  "state", "Mapped & Active", "", ""
)
or
label_replace(vector(0), "state", "Mapped & Active", "", "")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      storage_type="volume",
      netapp_storage_type!="lun",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            storage_type="volume",
            netapp_storage_type!="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    ),
    "state", "Mapped & Active", "", ""
  )
)

