label_replace(vector(0), "state", "Unmapped", "", "")

label_replace(
  sum(
    storage_usage_bytes{storage_consumer_state="unmapped", storage_type="volume", netapp_storage_type!="lun", storage_provisioning_state="used"}
  ),"state", "Unmapped", "", ""
)
or
label_replace(vector(0), "state", "Unmapped", "", "")

label_replace(
  count(
    sum by (host_name, id) (
      storage_limit_bytes{storage_type="volume", netapp_storage_type!~"volume|lun"}
    )
    unless on (host_name, id)
    storage_usage_bytes{storage_type="volume", netapp_storage_type!~"volume|lun", storage_consumer_state="unmapped"}
    unless on (host_name, id)
    (
      storage_usage_bytes{storage_type="volume", netapp_storage_type!~"volume|lun", storage_consumer_state="mapped"}
      and on (host_name, id)
      sum by (host_name, id) (
        rate(storage_operations_total{storage_type="volume", netapp_storage_type!~"volume|lun", storage_io_direction=~"read|write"}[$__range])
      )
    )
  ),
  "state", "Not Enough Data", "", ""
)
or
label_replace(vector(0), "state", "Not Enough Data", "", "")

# Total capacity of unmapped and inactive volumes
sum(
  storage_usage_bytes{
    storage_type="volume",
    netapp_storage_type!="lun",
    storage_consumer_state="unmapped",
    storage_provisioning_state="used"
  }
  or
  (
    storage_usage_bytes{
      storage_type="volume",
      netapp_storage_type!="lun",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            storage_type="volume",
            netapp_storage_type!="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    )
    unless on (host_name, id)
    (storage_status{storage_type="volume", netapp_storage_type!="lun", state=~"failed"} > 0)
  )
) or vector(0)

# Failed Capacity
sum(
  storage_usage_bytes{storage_type="volume", netapp_storage_type!="lun", storage_consumer_state="mapped", storage_provisioning_state="used"}
  and on (host_name, id)
  storage_status{storage_type="volume", netapp_storage_type!="lun", state=~"failed"} > 0
) or vector(0)

# Active Capacity
sum(
  storage_usage_bytes{storage_type="volume", netapp_storage_type!="lun", storage_consumer_state="mapped", storage_provisioning_state="used"}
  and on (host_name, id)
  (
    sum by (host_name, id) (
      rate(
        storage_operations_total{
          storage_type="volume",
          netapp_storage_type!="lun",
          storage_io_direction=~"read|write"
        }[$__range]
