        ) <= 0.001
      )
      unless on (host_name, id)
      (storage_status{storage_type="volume", state=~"failed"} > 0)
    )
  )
  or
  0 * count by (host_name) (
    storage_limit_bytes{storage_type="volume"}
    and on (host_name, id)
