      storage_consumer_state="unmapped"
    }
  )
)

sum by (host_name) (
  storage_usage_bytes{
    netapp_storage_type="lun",
    storage_consumer_state="unmapped",
    storage_provisioning_state="used"
  }
)

sum by (host_name) (
  storage_usage_bytes{
    netapp_storage_type="lun",
    storage_consumer_state="unmapped",
    storage_provisioning_state="used"
  }
  or
  (
    (
      storage_usage_bytes{
        netapp_storage_type="lun",
        storage_provisioning_state="used"
      }
      unless on (host_name, id)
      storage_usage_bytes{
        netapp_storage_type="lun",
        storage_consumer_state="unmapped",
        storage_provisioning_state="used"
      }
    )
    unless on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            netapp_storage_type="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    )
    unless on (host_name, id)
    (
      storage_status{
        netapp_storage_type="lun",
        state=~"failed"
      } > 0
    )
  )
)
